export async function fetchResource({ skillId, path, bridgeBase, fetcher } = {}) {
  const doFetch = fetcher ?? globalThis.fetch;
  if (typeof doFetch !== "function") throw new Error("fetchResource: no fetch implementation available");
  const url = `${String(bridgeBase ?? "").replace(/\/$/, "")}/files/read`;
  const res = await doFetch(url, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ skill_id: skillId, path }),
  });

  const envelope = await readEnvelope(res);

  if (envelope && typeof envelope.code === "number") {
    if (envelope.code !== 0) {
      throw new Error(envelope.message ?? `skill bridge error (code ${envelope.code})`);
    }
    const data = envelope.data ?? {};
    if (data.content !== undefined && data.content !== null) {
      return data.encoding === "base64"
        ? Buffer.from(String(data.content), "base64")
        : Buffer.from(String(data.content), "utf-8");
    }
    // code 0 but no content field: an empty (or content-less) resource is still a legal file.
    return Buffer.alloc(0);
  }

  // Not an envelope: treat the body as the resource's raw bytes.
  return envelope === null ? Buffer.alloc(0) : Buffer.isBuffer(envelope) ? envelope : Buffer.from(String(envelope), "utf-8");
}
