export async function fetchResource({ skillId, path, bridgeBase, fetcher } = {}) {
  const doFetch = fetcher ?? globalThis.fetch;
  if (typeof doFetch !== "function") throw new Error("fetchResource: no fetcher available (globalThis.fetch is not a function)");
  const base = String(bridgeBase ?? "").replace(/\/+$/, "");
  const res = await doFetch(`${base}/files/read`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ skill_id: skillId, path }),
  });
  const { bytes, parsed } = await responseBody(res);
  if (parsed && typeof parsed.code === "number") {
    if (parsed.code !== 0) throw new Error(parsed.message ?? `skill bridge error (code ${parsed.code})`);
    const data = parsed.data ?? {};
    if (data.content === undefined || data.content === null) return Buffer.alloc(0);
    return data.encoding === "base64"
      ? Buffer.from(String(data.content), "base64")
      : Buffer.from(String(data.content), "utf-8");
  }
  return bytes ?? Buffer.alloc(0);
}
